#!/usr/bin/env python3
"""Render one explicit completion ledger into front-page and every core README."""
import argparse,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
START='<!-- completion:start -->'
END='<!-- completion:end -->'
def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--check',action='store_true');args=p.parse_args()
    data=json.loads((ROOT/'docs/core-completion.json').read_text())
    milestones={m['id']:m['acceptance'] for m in data['milestones']}
    assert data['schema']==1 and len(milestones)==20
    def percent(row):
        assert len(set(row['delivered']))==len(row['delivered']) and set(row['delivered'])<=milestones.keys()
        return 100*len(row['delivered'])//len(milestones)
    def table(rows):
        lines=['| Platform | Delivery checklist completion | Delivered / total |','|---|---:|---:|']
        for row in rows:lines.append(f"| {row['name']} | **{percent(row)}%** | {len(row['delivered'])}/20 |")
        return '\n'.join(lines)
    by_file={}
    for row in data['platforms']:by_file.setdefault(row['readme'],[]).append(row)
    legend='These percentages count the 20 explicit delivery milestones in [the completion ledger]({link}); partial or unverified milestones receive zero credit. Each milestone is worth 5 percentage points. **They are not percentages of native hardware accuracy or retail compatibility.** Bounded profile tests do not complete a whole CPU or hardware subsystem.'
    blocks={'README.md':'## Core completion percentages\n\n'+table(data['platforms'])+'\n\n'+legend.format(link='docs/CORE-COMPLETION.md')+'\n\nSuper Mario 64 (USA) was tested locally on 2026-10-11. The six-billion-attempt intro reaches the courtyard. A shared private checkpoint now verifies **analog walking, A jumping and B punching through actual RAM fields**, with stationary neutral controls and no terminal CPU/RSP/DP stop during those continuations. **180 legacy quantum movie frames and six seek boundaries match complete native states**; an executed neutral movie leaves Mario standing. New native sessions advance on **VI field boundaries**, with an original **5,160-case file oracle** and **121 VI movie frames / six exact seeks**; legacy states retain the old budget. A private [castle-entry regression](tests/n64_retail_castle_entry.py) verifies Lakitu dialogue, A dismissal, the castle door pull and the lobby transition through actual guest RAM, two neutral controls and local frame captures. A [lobby continuation](tests/n64_retail_lobby.py) verifies the automatic welcome dialogue, A dismissal and movement into the raised main hall, with a neutral control. A [painting-room continuation](tests/n64_retail_painting_room.py) verifies the left zero-star door push and entry into the Bob-omb painting room, with a neutral door control. A [Course 1 continuation](tests/n64_retail_course_entry.py) now enters Bob-omb Battlefield, dismisses its opening dialogue and verifies analog walking through guest RAM and rendered frames. This uses a bounded two-cycle RDP fog profile; practical normal-speed play, full-title playability and native firmware boot remain unverified. **N64 stays at 50%** of the fixed delivery checklist. Its original signed-stick corpus grades 65,536 cases / 1,048,576 RAM/register words; the original one-cycle rectangle corpus grades 1,048,576 cases / 13,631,488 words. All twelve integer trap instructions are now verified by an original **15,728,640-case ROM / 188,743,680 RAM/CP0 words**. Linked word/doubleword loads and conditional stores now have an original **1,048,576-case ROM / 10,485,760 RAM words**, including ERET failures and a live-link checkpoint. Disabled COP2 exception priority now has an original **9,056,256-case ROM / 108,675,072 RAM/CP0 words**, plus an exhaustive encoded-payload component gate. Four local controller ports now pass **194 ordinary frontend cases / 1,164 guest RAM words**, including all 24 device assignments and an executed wrong-route rejection. Independent extra-player profiles pass **3,026 remap/persistence cases / 18,156 guest RAM words** and remapped four-port movies. CP0 physical Watch traps now have an original **4,194,816-case ROM / 58,727,424 RAM/CP0 words**, with armed-checkpoint replay and R/W/EXL controls.\n\nTwenty-eight doubleword integer/LWU families now enforce User/Supervisor mode restrictions: **5,768,792 original guest cases / 69,225,504 RAM/CP0 words**, with executed NOP rejection and native checkpoint/rollback. Nine wide integer memory families now verify Kernel32 address formation: **4,718,592 original guest cases / 56,623,104 RAM/CP0 words**, with extended-address/alignment controls and native rollback. CP0 BadVAddr/PRId/CacheErr write protection now has an original **12,582,912-case cartridge / 150,994,944 actual RAM/register words**, with hardware exception seeding, executed wrong-read rejection and native rollback. Config fixed/writable fields and actual K0 cache/bypass reads now have an original **16,777,216-case cartridge / 201,326,592 actual RAM/register words**, with EP/BE defaults held and clock-field preservation controls. Status writable/reserved/TS write rules now have an original **4,194,304-case cartridge / 50,331,648 actual RAM/register words**, with safe EXL-held readbacks and unconstrained component controls. TagLo/TagHi/PErr field writes now have an original **12,582,912-case cartridge / 150,994,944 actual RAM/register words**, plus every physical tag in defined functional CACHE consumer controls. This remains partial CPU coverage; N64 stays 50%. Per-player analog sources, inversion, dead zone and range now have **4,035 ordinary frontend cases / 24,210 actual guest RAM words**, saved-profile migration and remapped four-port native movies. Physical controller calibration/peripherals, general two-cycle graphics/LOD, enabled expansion-coprocessor behavior, precise atomic/cache interference and full CPU/hardware/audio/timing remain unfinished. See [checkpoint control and movie evidence](cores/n64/README.md#private-courtyard-controls-and-movie-checkpoints).'}
    blocks['README.md']+='\n\nGame Boy Color KEY1/STOP speed switching now has an [original register-output cartridge](tests/roms-src/gb/cgb_speed_switch/README.md) with **517 actual KEY1 readbacks**: five transition states and every possible write byte at both speeds. An independent file oracle grades all values and rejects an executed disarmed-STOP ROM. CPU versus LCD/audio pacing is implemented, while LCD phase, transient bus behavior and broader peripheral timing remain pending. Game Boy / Color stays **40% (8/20)**.'
    blocks['README.md']+='\n\nN64 0.58.0 adds functional 4 Kbit cartridge EEPROM reads, writes, frontend battery persistence and S032 rollback state. Its [original EEPROM cartridge](tests/roms-src/n64/eeprom_4k/README.md) passes **16,512 guest cases / 33,024 actual register words**, including all 64 block addresses, 256 payload patterns per block, a cross-process save reload, malformed-save rejection and an executed wrong-read control. This is partial save-media coverage; N64 remains **50% (10/20)**. Super Mario 64 course entry and full-title playability remain unverified.'
    blocks['README.md']+='\n\nN64 0.59.0 adds functional 16 Kbit EEPROM reads and writes across all 256 blocks. The [original 16 Kbit cartridge](tests/roms-src/n64/eeprom_16k/README.md) grades **66,048 guest cases / 132,096 register words**, with 2,048-byte cross-process persistence, S033 rollback, S032 import, malformed-save rejection and an executed wrong-read control. N64 stays **50% (10/20)**.'
    blocks['README.md']+='\n\nN64 0.60.0 selects 16 Kbit EEPROM for [23 documented native cartridge IDs](tests/roms-src/n64/native_save_identity/README.md). A repository-built native ROM grades the guest\'s SI/PIF identity response for those IDs, four 4 Kbit controls and both swapped ROM formats, and writes all 30 guest `$t2` values to `build/artifacts/owned/n64_native_save_identity/registers.txt`. Unknown 16 Kbit IDs still require an existing 2,048-byte save or explicit media selection. Super Mario 64 course entry remains unverified. N64 stays **50% (10/20)**.'
    blocks['README.md']+='\n\nN64 0.61.0 adds correct absent-controller-accessory replies for Joybus read/write commands. Its [original MIPS cartridge](tests/roms-src/n64/accessory_absent/README.md) captures **2,048 guest SI packets / 16,384 actual register words** across all four ports, with an independent file oracle and an executed wrong-register control. Controller Pak insertion, storage and persistence remain unfinished; N64 stays **50% (10/20)**.'
    blocks['README.md']+='\n\nN64 0.62.0 adds configurable 32 KiB Controller Paks on four ports, addressed Joybus reads and writes, deterministic fresh-Pak formatting, S034 rollback state and frontend `.mpk1` through `.mpk4` persistence. A component gate writes and rereads all **4,096 Pak blocks** across four ports; state and frontend gates cover rollback, cross-session reload and malformed-file rejection. The private Super Mario 64 lobby checkpoint is rerun as a compatibility gate. Other save media and complete accessory behavior remain pending; N64 stays **50% (10/20)**.'
    blocks['README.md']+='\n\nN64 0.64.0 extends the [original Controller Pak MIPS cartridge](tests/roms-src/n64/controller_pak/README.md) to read each fresh Pak’s five system pages, create and read back a synthetic one-page note on each port, then sweep all 4,096 storage blocks. The host checks four copied ID headers, their checksums, both inode tables, the note directory and data chain from guest SI replies. It grades **12,540 guest packets / 100,320 register words** and the final **131,072 Pak bytes**. An executed wrong-register ROM and damaged files are rejected. Retail game filesystem APIs and physical serial timing remain unverified; N64 stays **50% (10/20)**.'
    blocks['README.md']+='\n\nN64 0.65.0 adds per-port Rumble Pak accessory commands, SDL controller feedback and S035 motor rollback. An [original MIPS cartridge](tests/roms-src/n64/rumble_pak/README.md) grades **24,596 complete SI packets / 196,768 guest register words** across four ports and all 2,048 aligned accessory addresses in three motor phases. An executed wrong-register ROM, malformed files, virtual SDL feedback routing and state import/rollback are checked. Physical N64 hardware and controller feedback remain unverified; N64 stays **50% (10/20)**.'
    blocks['README.md']+='\n\nN64 0.66.0 adds 32 KiB and 96 KiB cartridge SRAM via PI DMA, direct aligned I/O, frontend save persistence and S036 rollback. Its [original MIPS cartridge](tests/roms-src/n64/cartridge_sram/README.md) grades **2,048 guest DMA cases / 24,576 register words** and **131,072 saved bytes**, with executed wrong-register and damaged-file controls. Known native SRAM IDs select the right media; existing saves can identify unknown native boards. FlashRAM and physical PI timing remain pending. N64 stays **50% (10/20)**.'
    blocks['README.md']+='\n\nN64 0.67.0 adds functional 128 KiB FlashRAM page programming, silicon ID, sector and chip erase, PI DMA, frontend `.sav` persistence and S037 rollback. Its [original MIPS cartridge](tests/roms-src/n64/cartridge_flash/README.md) grades **1,024 guest page cases / 20,480 register words** and **131,072 saved bytes**, with an executed wrong-register control and damaged-file rejection. Known native IDs select both Macronix models; existing 128 KiB saves can identify unknown native boards. Physical timing, busy status and retail save APIs remain unverified. N64 stays **50% (10/20)**.'
    blocks['README.md']+='\n\nA second [original native FlashRAM identity cartridge](tests/roms-src/n64/native_flash_identity/README.md) executes silicon-ID PI DMA reads for all 20 known native IDs and both swapped ROM formats. The independent file oracle grades **22 guest cases / 44 actual register words**, with an executed wrong-register control and damaged-file rejection. Each case selects erased 128 KiB media; eight use the older Macronix ID. Physical timing and retail save APIs remain pending. N64 stays **50% (10/20)**.'
    blocks['README.md']+='\n\nN64 0.68.0 adds functional cartridge RTC Joybus status, block reads and writes for the native `NAF` board, S038 rollback, and offline clock persistence beside its 128 KiB FlashRAM. The [original RTC cartridge](tests/roms-src/n64/cartridge_rtc/README.md) grades **13 actual guest Joybus reply bytes** from a register file, with an executed wrong-register control and damaged-file rejection. Leap-day rollover, stop and write-lock controls, cross-session reload, malformed saves and legacy FlashRAM import have component/frontend gates. Fresh clocks start at 2000-01-01 UTC; oscillator drift, physical timing, 64DD RTC and full retail behavior remain pending. N64 stays **50% (10/20)**.'
    blocks['README.md']+='\n\nN64 0.69.0 introduced a bounded two-cycle RDP fog profile used by the private Bob-omb Battlefield course-entry regression. The [original two-cycle cartridge](tests/roms-src/n64/rdp_two_cycle_fog/README.md), expanded in 0.70.0, now grades **524,288 guest cases / 6,815,744 actual framebuffer and DP/MI register words** from a file, including both RDRAM and XBUS command paths. Its independent oracle, executed wrong-capture ROM and damaged-stream controls pass. General two-cycle graphics, complete course gameplay and full-title playability remain pending; N64 stays **50% (10/20)**.'
    blocks['README.md']+='\n\nN64 0.70.0 implements the first-cycle fog-register-alpha selector alongside shade-alpha fog. The expanded original cartridge sweeps both sources over every 8-bit seed/primitive-alpha pair and two second-cycle blend profiles; a component gate checks 65,536 fog-register pixel combinations. A separately executed wrong-alpha-selector ROM is rejected by the file oracle. Fog alpha and shade alpha are correlated in the guest corpus. Other two-cycle blender modes and full hardware accuracy remain pending; N64 stays **50% (10/20)**.'
    blocks['README.md']+='\n\nN64 0.71.0 adds first-cycle `G_RM_PASS` in the bounded two-cycle blender. The [original PASS cartridge](tests/roms-src/n64/rdp_two_cycle_pass/README.md) grades **262,144 guest cases / 3,407,872 actual framebuffer and DP/MI register words**. CC0 and CC1 produce different colors; an executed wrong-first-stage ROM is rejected by the file oracle. Other two-cycle blender modes and full hardware accuracy remain pending; N64 stays **50% (10/20)**.'
    blocks['README.md']+='\n\nThe companion [original textured two-cycle cartridge](tests/roms-src/n64/rdp_two_cycle_texture/README.md) grades another **262,144 guest cases / 3,407,872 actual framebuffer and DP/MI register words**. It loads every 16-bit RGBA16 and IA16 TEXEL0 pattern into TMEM, forwards it through cycle-one COMBINED, and checks framebuffer blending under RDRAM and XBUS delivery. The finite corpus uses point sampling and zero fog factor; general textured two-cycle behavior remains pending. N64 stays **50% (10/20)**.'
    blocks['README.md']+='\n\nA third [original shaded-texture cartridge](tests/roms-src/n64/rdp_two_cycle_shaded_texture/README.md) grades **262,144 guest cases / 3,407,872 actual framebuffer and DP/MI register words** with TEXEL0×SHADE, COMBINED feedback, nonzero fog color and shade alpha, and framebuffer blending. Its independent oracle and executed wrong-capture control pass. Shade alpha is correlated with the texture byte; independent shade patterns, filtering, depth and general two-cycle hardware remain unfinished. N64 stays **50% (10/20)**.'
    blocks['README.md']+='\n\nThe private [Bob-omb Battlefield continuation](tests/n64_retail_course_entry.py) now branches from the same walking checkpoint for **300 VI fields** of neutral and sustained stick input. Guest RAM and local frames show Mario settling near (-5767, 128, 5808) in the control and moving to about (-2020, 0, 3407) with stick input, without RSP/DP stops. This remains bounded course movement; N64 stays **50% (10/20)**.'
    blocks['README.md']+='\n\nN64 0.72.0 samples cycle-one TEXEL1 from the tile after the primitive tile when LOD is disabled. The [original two-tile cartridge](tests/roms-src/n64/rdp_two_cycle_texel1/README.md) initially graded **262,144 guest cases / 3,407,872 actual framebuffer and DP/MI register words** across RGBA16 and IA16, with RDRAM and XBUS command delivery. Its independent oracle rejects an executed wrong-second-tile ROM. Point sampling, fixed primitive alpha and no LOD define this finite profile; wider graphics and full-title playability remain pending. N64 stays **50% (10/20)**.'
    blocks['README.md']+='\n\nN64 0.73.0 expands the [original two-tile cartridge](tests/roms-src/n64/rdp_two_cycle_texel1/README.md) to **786,432 guest cases / 10,223,616 actual framebuffer and DP/MI register words**. Cycle one now accepts TEXEL0 RGB and either texel alpha as an interpolation coefficient, alongside primitive alpha. An executed wrong-alpha-selector ROM is rejected. The tile alphas are complementary in this point-sampled, no-LOD corpus; full graphics and retail compatibility remain pending. N64 stays **50% (10/20)**.'
    blocks['README.md']+='\n\nN64 0.74.0 adds [original two-tile filtering evidence](tests/roms-src/n64/rdp_two_cycle_filter/README.md): **65,536 guest cases / 851,968 actual framebuffer and DP/MI register words** covering every 5-bit fractional S/T pair, RGBA16 and IA16, triangular and mid-texel filters, eight primitive-alpha values and RDRAM/XBUS command delivery. Executed wrong-tile, point-sampling and wrong-mid-texel ROMs are rejected. The tile data are fixed, LOD and perspective are untested in this corpus, and N64 stays **50% (10/20)**.'
    blocks['README.md']+='\n\nN64 0.75.0 implements constant-coordinate two-cycle LOD magnification: both texture cycles use the primitive tile when LOD is enabled with detail/sharpen off. The [original LOD cartridge](tests/roms-src/n64/rdp_lod_magnify/README.md) grades **524,288 cases / 6,815,744 actual framebuffer and DP/MI register words** across all 16-bit RGBA16 and IA16 patterns, LOD on/off and RDRAM/XBUS delivery. Wrong-LOD and wrong-tile ROMs are rejected. Variable LOD, mipmap chains, LOD fractions and full hardware accuracy remain pending; N64 stays **50% (10/20)**.'
    blocks['README.md']+='\n\nN64 0.76.0 adds affine integer-gradient LOD tile selection. The [original tile-level cartridge](tests/roms-src/n64/rdp_lod_affine_levels/README.md) grades **8,192 cases / 106,496 actual framebuffer and DP/MI register words** across all 0–255 texel-per-pixel S gradients in both directions, two maximum levels, LOD on/off, RGBA16/IA16 and RDRAM/XBUS delivery. Executed wrong-tile, wrong-LOD and wrong-maximum-level ROMs are rejected. Fractional/T/Y gradients, perspective, LOD fractions and general mipmaps remain pending; N64 stays **50% (10/20)**.'
    blocks['README.md']+='\n\nN64 0.77.0 routes exact affine LOD fractions into two-cycle RGB and alpha combiner multipliers. The [original LOD-fraction cartridge](tests/roms-src/n64/rdp_lod_fraction/README.md) grades **360 cases / 4,680 actual framebuffer and DP/MI register words** across 1–15 texel-per-pixel gradients in both directions, RGB-only/alpha-only/combined fraction muxes, RGBA16/IA16 and RDRAM/XBUS delivery. Executed wrong-fraction and wrong-tile ROMs are rejected. That cartridge does not grade capped fractions, nonzero minimum level, fractional/T/Y gradients, perspective, detail/sharpen or full mipmap filtering; N64 stays **50% (10/20)**.'
    blocks['README.md']+='\n\nN64 0.78.0 selects the affine LOD level and fraction from the largest S/T gradient along either screen axis. The [original four-axis cartridge](tests/roms-src/n64/rdp_lod_affine_2d/README.md) grades **524,280 cases / 6,815,640 actual framebuffer and DP/MI register words** over every nonzero four-tuple of 0–15 integer texels per pixel, both common signs, RGBA16/IA16 and RDRAM/XBUS delivery. Executed wrong-T, wrong-Y, wrong-fraction and wrong-tile ROMs are rejected. That corpus does not grade fractional gradients, independent signs, perspective or general mipmap filtering; N64 stays **50% (10/20)**.'
    blocks['README.md']+='\n\nN64 0.79.0 adds affine 1/32-texel LOD gradients and corrects signed-delta and coarsest-level behavior. The [original subtexel cartridge](tests/roms-src/n64/rdp_lod_subtexel/README.md) grades **49,152 cases / 638,976 actual framebuffer and DP/MI register words** across all 0–511 subtexel steps on four axes, both signs, three maximum levels, RGBA16/IA16 and RDRAM/XBUS delivery. Earlier integer-gradient oracles were corrected and rerun. Mixed fractional gradients, perspective, detail/sharpen and full mipmap filtering remain pending; direct physical-hardware comparison is also pending. N64 stays **50% (10/20)**.'
    blocks['README.md']+='\n\nN64 0.80.0 calculates affine LOD from screen-X/Y texture gradients independently of triangle-edge interpolation. The [original edge-gradient cartridge](tests/roms-src/n64/rdp_lod_edge_gradient/README.md) grades **165,760 cases / 2,154,880 actual framebuffer and DP/MI register words** across mixed 1/32-texel vectors, 16 independent sign masks, two edge arrangements, RGBA16/IA16 and RDRAM/XBUS delivery. A changed-edge control preserves observations while executed wrong-T, wrong-Y, wrong-sign, wrong-fraction and wrong-tile ROMs are rejected. Perspective LOD, detail/sharpen, non-solid edge-interpolation observations and full mipmap filtering remain pending; N64 stays **50% (10/20)**.'
    blocks['README.md']+='\n\nN64 0.81.0 computes two-cycle LOD from adjacent perspective-divided texture coordinates per pixel for constant-W triangles. The [original perspective-LOD cartridge](tests/roms-src/n64/rdp_lod_perspective/README.md) grades **147,456 cases / 1,916,928 actual framebuffer and DP/MI register words** across 0–255 subtexel input gradients on four axes, both signs, six W values, three maximum levels, RGBA16/IA16 and RDRAM/XBUS delivery. Non-power-of-two W values exercise within-triangle LOD variation; executed wrong-W, wrong-T, wrong-Y, wrong-fraction and wrong-tile ROMs are rejected. Varying W, perspective overflow, mixed derivatives, detail/sharpen and full mipmap filtering remain pending; N64 stays **50% (10/20)**.'
    blocks['README.md']+='\n\nN64 0.82.0 extends two-cycle perspective LOD to changing W along screen X and Y. The [original varying-W cartridge](tests/roms-src/n64/rdp_lod_varying_w/README.md) grades **147,456 cases / 1,916,928 actual framebuffer and DP/MI register words** across 0–127 subtexel S/T gradients on four axes, both signs, six W slope pairs, two W bases, three maximum levels, RGBA16/IA16 and RDRAM/XBUS delivery. The independent reciprocal oracle checks per-pixel LOD and rejects an executed zero-W-gradient ROM. W overflow, arbitrary fractional gradients, detail/sharpen and full mipmap filtering remain pending; N64 stays **50% (10/20)**.'
    blocks['README.md']+='\n\nN64 0.83.0 verifies mixed S/T/W perspective LOD gradients and division-overflow clamping with the [original mixed-gradient cartridge](tests/roms-src/n64/rdp_lod_perspective_mixed/README.md). Its independent reciprocal oracle grades **24,576 cases / 319,488 actual framebuffer and DP/MI register words** across eight S/T vectors, all 16 sign masks, two edge gradients, four W values including zero and negative W, six W-gradient pairs, RGBA16/IA16 and RDRAM/XBUS delivery. Executed wrong-edge, wrong-sign, wrong-W, wrong-W-sign, wrong-zero-W, wrong-tile and wrong-fraction ROMs are rejected. Arbitrary fractional gradients, non-solid mipmap filtering and detail/sharpen remain pending; N64 stays **50% (10/20)**.'
    blocks['README.md']+='\n\nN64 0.84.0 implements two-cycle detail and sharpen texture modes, signed sharpening fractions, minimum-LOD clamping and detail tile offsets. The [original detail/sharpen cartridge](tests/roms-src/n64/rdp_lod_detail_sharpen/README.md) grades **433,152 cases / 5,630,976 actual framebuffer and DP/MI register words** across all four mode combinations and 32 minimum-LOD values, 47 gradient magnitudes, both signs, three maximum levels, affine/perspective/zero-W profiles, RGBA16/IA16 and RDRAM/XBUS delivery. Executed mode, minimum, maximum, sign, perspective, tile and fraction mutants are rejected. Non-solid mipmap filtering, arbitrary fractional derivatives and physical timing remain pending; N64 stays **50% (10/20)**.'
    blocks['README.md']+='\n\nN64 0.85.0 accelerates cached idle loops and inactive device clocks while preserving complete native state and interrupt timing in the functional model. The [paired performance benchmark](docs/N64-PERFORMANCE.md) measured **1.56x throughput (8.17 to 12.75 VI fields/second)** on this machine across three private SM64 checkpoint pairs, with identical full states, CPU attempts and audio counts. CPU/cache/timer continuation checks, 128 full machine continuations, original interrupt/VI scheduling ROMs and netplay pass. This is still below real time; RSP and software RDP performance, full-title playability and physical timing remain pending. N64 stays **50% (10/20)**.'
    blocks['README.md']+='\n\nN64 0.86.0 adds SSE2 RSP multiply/accumulate and ALU/merge acceleration with a retained scalar path. The [paired benchmark](docs/N64-PERFORMANCE.md) measured **10.8% more throughput (12.61 to 13.98 VI fields/second)** than 0.85.0 on this machine, with identical complete states in three private SM64 pairs. The scalar comparison covers **2,359,296 seeded continuations**; six original ROM subsets grade **4,240 cases / 77,328 actual register words** and reject executed mutants. Hardware arithmetic fixtures, portable fallback, netplay and the private course continuation pass. N64 remains below real time and **50% (10/20)**; software RDP performance and full-title playability remain unfinished.'
    blocks['README.md']+='\n\nN64 0.87.0 accelerates unpaletted RGBA16 quad decoding with SSE2 and retains the scalar fallback. Five [paired SM64 checkpoint runs](docs/N64-PERFORMANCE.md) measured **3.9% more throughput (13.35 to 13.88 VI fields/second)** than 0.86.0, with identical complete states, CPU attempts and audio counts. Exhaustive packed-color decoding, independent texture-addressing and forced-fallback oracles, executed mutants, original two-cycle rendering, private course movement and netplay pass. Performance remains below real time; **N64 remains 50% (10/20)**.'
    blocks['README.md']+='\n\nN64 0.88.0 accelerates settled DP clock accounting after RSP steps. Five [paired SM64 checkpoint runs](docs/N64-PERFORMANCE.md) measured **2.9% more throughput (14.07 to 14.47 VI fields/second)** than 0.87.0, with identical complete states, CPU attempts and audio counts. A differential gate covers **40,960 DP ticks and 128 full states**; the original DP register ROM, netplay and private course continuation pass. Performance remains below real time; **N64 remains 50% (10/20)**.'
    blocks['README.md']+='\n\nN64 0.89.0 batches quiet device clocks while executing every active RSP and DP tick during cached CPU idle. Five [paired SM64 checkpoint runs](docs/N64-PERFORMANCE.md) measured **9.5% more throughput (14.36 to 15.73 VI fields/second)** than 0.88.0, with identical complete states, CPU attempts and audio counts. The differential gate compares **128 full machine continuations** against both unbatched and ordinary CPU execution; original timing/register ROMs, netplay and private course movement pass. Performance remains below real time; **N64 remains 50% (10/20)**.'
    blocks['README.md']+='\n\nN64 0.90.0 checks new SP/DP interrupts only after active RSP/DP ticks in cached-idle batches. Five [paired SM64 checkpoint runs](docs/N64-PERFORMANCE.md) measured **4.0% more throughput (16.46 to 17.12 VI fields/second)** than 0.89.0, with identical complete states, CPU attempts and audio counts. The **128-state differential gate** exercises RSP BREAK and DP FullSync interrupts; original interrupt ROMs, netplay and private course movement pass. Performance remains below real time; **N64 remains 50% (10/20)**.'
    blocks['README.md']+='\n\nN64 0.91.0 adds an optional local GCC [profile-guided N64 plugin build](docs/N64-PERFORMANCE.md). Five paired SM64 checkpoint runs measured **5.6% more throughput (16.83 to 17.77 VI fields/second)** than a normal 0.90.0 release build, with identical complete states, CPU attempts and audio counts. The trained plugin passes original register ROMs, netplay and private course movement. Generated profiles and private ROM data stay local. Performance remains below real time; **N64 remains 50% (10/20)**.'
    blocks['README.md']+='\n\nN64 player one now reads the analog stick from a sole unassigned controller, matching the existing out-of-the-box digital button fallback. Assigned secondary pads stay isolated, and two eligible unassigned pads require an explicit choice. SDL virtual-pad hotplug tests exercise the default input plugin and routing. This input fix does not change the N64 core milestone score: **50% (10/20)**.'
    blocks['README.md']+='\n\nN64 0.92.0 speeds up exact RDP perspective division with a portable floor-shift identity. The independent exhaustive divider oracle passes **4,294,967,296 ST/W pairs** and **524,288** saturation encodings; the original perspective texture ROM grades **1,572,864 guest cases / 20,447,232 actual framebuffer and register words**. Five paired production-build SM64 checkpoint runs measured **3.2% more VI-field throughput (16.65 to 17.19 fields/second)** with identical complete states, CPU attempts and audio counts. A retrained optional PGO build added **3.8%** over ordinary 0.92.0. Performance remains below real time; **N64 remains 50% (10/20)**.'
    blocks['README.md']+='\n\nN64 0.93.0 adds exact fast paths for two common RDP cycle-one selector patterns. An independent routing oracle passes **525,312 nine-bit source cases**; the original shaded-texture cartridge grades **262,144 guest cases / 3,407,872 actual framebuffer and register words** and rejects an executed wrong capture. Five paired production-build SM64 checkpoint runs measured **3.1% more throughput (17.97 to 18.54 VI fields/second)** with identical complete states, CPU attempts and audio counts. A freshly trained optional PGO build reaches **18.99 fields/second** in a separate five-pair run. Performance remains below real time; **N64 remains 50% (10/20)**.'
    blocks['README.md']+='\n\nN64 0.94.0 caches fetched RSP instruction words until CPU stores or SP DMA change IMEM. Five paired 300-field SM64 course-checkpoint runs measured **3.3% more throughput (18.39 to 19.00 VI fields/second)** than ordinary 0.93.0, with identical complete states, CPU attempts and audio counts. The RSP unit and original acceleration ROM gates, private course continuation and production netplay pass. [Performance details](docs/N64-PERFORMANCE.md). Performance remains below real time; **N64 remains 50% (10/20)**.'
    blocks['README.md']+='\n\nAn optional [N64-only host CPU build](docs/N64-PERFORMANCE.md#optional-host-cpu-optimization) applies `-march=native` on local GCC/Clang builds. Nine CPU-pinned SM64 course-checkpoint pairs measured **17.35 to 18.27 VI fields/second** by median time, with identical complete states and work counts; individual runs varied. Original RSP ROMs and production netplay pass. The portable build remains the default, performance remains below real time, and **N64 stays 50% (10/20)**.'
    blocks['README.md']+='\n\nThe [original RSP IMEM rewrite cartridge](tests/roms-src/n64/rsp_imem_rewrite/README.md) grades **512 cases / 1,536 actual register words** after CPU stores and SP DMA rewrite the same instruction slot. The file oracle rejects an executed wrong-instruction cartridge and malformed output. This checks functional instruction-cache visibility; wider IMEM address coverage and physical timing remain pending. **N64 stays 50% (10/20)**.'
    blocks['README.md']+='\n\nN64 0.95.0 uses an exact 256-entry RDP coverage derivative table. Five CPU-pinned, paired 300-field Super Mario 64 course-checkpoint runs measured a **1.9% median paired throughput gain (18.52 to 19.00 VI fields/second)**, with all five pairs faster and byte-identical complete states. The independent coverage oracle and original two-cycle rendering cartridges pass. [Performance details](docs/N64-PERFORMANCE.md). Play remains below real time; **N64 stays 50% (10/20)**.'
    blocks['README.md']+='\n\n### 3DS ARM11 instruction coverage\n\nThe 3DS plugin implements the following ARMv6 instruction subsets. Each linked\noriginal ROM emits actual register words, has independent host grading and\nexecuted negative controls. Checkpoint gates compare native state continuations.\nThese are finite documented domains; **3DS remains 30%** of the delivery checklist.\n\n| Implemented subset / original source | Register snapshots | Actual words |\n|---|---:|---:|\n| [ARM/Thumb REV, REV16, REVSH](tests/roms-src/3ds/reversal_registers/README.md) | 25,165,824 | 176,160,768 |\n| [Signed/unsigned extension and accumulation](tests/roms-src/3ds/extend_registers/README.md) | 13,631,488 | 95,420,416 |\n| [Scalar and dual-halfword SSAT/USAT](tests/roms-src/3ds/saturation_registers/README.md) | 12,582,912 | 88,080,384 |\n| [36 parallel arithmetic forms, GE and SEL](tests/roms-src/3ds/parallel_registers/README.md) | 19,922,944 | 179,306,496 |\n| [Halfword packing and unsigned byte differences](tests/roms-src/3ds/pack_difference_registers/README.md) | 18,874,368 | 150,994,944 |\n| [UMAAL and signed high-word multiply/rounding](tests/roms-src/3ds/wide_media_multiply_registers/README.md) | 7,340,032 | 73,400,320 |\n| [Dual-halfword multiply, exchange and accumulation](tests/roms-src/3ds/dual_media_multiply_registers/README.md) | 12,582,912 | 125,829,120 |\n| [ARM11 exclusive memory and CLREX](tests/roms-src/3ds/exclusive_memory/README.md) | 5,242,880 | 52,428,800 |\n\nFull CPU/system/MMU/exception/privilege behavior, physical timing, native firmware/\nretail boot, graphics/audio and analog/touch/wireless devices remain unfinished.\nSee the [3DS core README](cores/3ds/README.md) for the implemented profile and limits.'
    blocks['README.md']+='\n\n### Switch memory instruction coverage\n\nThe AArch64 plugin executes these integer memory subsets in an original\nuncompressed NSO0 process profile. Independent file oracles grade actual\nregister/memory captures and executed faulty variants; native-state replay\nchecks successful and terminal-fault continuations.\n\n| Original source / implemented subset | Snapshots | Actual 64-bit words |\n|---|---:|---:|\n| [Integer pairs, signed-word pairs and writeback](tests/roms-src/switch/pair_transfer_registers/README.md) | 2,490,368 | 24,903,680 |\n| [Signed/unscaled/unprivileged/writeback/register-offset singles](tests/roms-src/switch/single_transfer_registers/README.md) | 7,188,480 | 57,507,840 |\n\nThese are finite documented domains. Full CPU/system/MMU/exception behavior,\nnative firmware/HOS/retail boot, graphics/audio and controllers remain\nunfinished. Production TCP rollback now matches complete states and eight independently\ngraded guest RAM words for two synthetic inputs; native Joy-Con/HID is pending.\nSee the [original netplay probe](tests/roms-src/switch/netplay_probe/README.md).\nSwitch is **30%** of the delivery checklist.'
    for path,rows in by_file.items():
        blocks[path]='## Completion percentage\n\n'+table(rows)+'\n\n'+legend.format(link='../../docs/CORE-COMPLETION.md')
        for row in rows:
            blocks[path]+='\n\n'+row['name']+' delivered milestones: '+', '.join(milestones[k] for k in row['delivered'])+'.' if row['delivered'] else '\n\nNo delivery milestones have been completed.'
            blocks[path]+='\n\nRemaining: '+row['remaining']
    blocks['docs/CORE-COMPLETION.md']='## Current completion\n\n'+table(data['platforms'])+'\n\n'+data['method']+'\n\n### Fixed acceptance checklist\n\n| ID | Acceptance |\n|---|---|\n'+'\n'.join('| '+key+' | '+value+' |' for key,value in milestones.items())+'\n\nNo native hardware subsystem is declared exhaustive from a bounded original ROM. The ledger credits the delivered register harness separately. Native analog peripherals, complete CPUs, hardware timing, full corpora and playable retail titles stay pending until evidence meets their full scope. A missing optional peripheral is not required on a platform that never had it; that platform must still fulfill the other native controller or CPU behavior in the same milestone.\n\nThe scores are conservative delivery tracking, with equal milestone weights rather than estimates of work hours. A high test pass rate can coexist with a low delivery percentage. An uncredited milestone can have substantial partial implementation. Detailed passing domains and remaining hardware are in [HARDWARE-COVERAGE.md](HARDWARE-COVERAGE.md) and [COMPLETENESS.md](../COMPLETENESS.md).\n\nEvidence entry points: each core README links its code, original-ROM sources, component gates and result artifacts. The scored `netplay` milestone requires a production two-process network gate, not just an interface declaration. `saves` requires the native media scope, so partial persistence is uncredited. Update [core-completion.json](core-completion.json) when new evidence completes a milestone; run `python3 tests/update_completion.py`, then `python3 tests/update_completion.py --check`. CI/CD remains disabled.'
    target=ROOT/'docs/CORE-COMPLETION.md'
    if not target.exists() and not args.check:target.write_text('# Core delivery completion ledger\n')
    bad=[]
    for path,block in blocks.items():
        target=ROOT/path;text=target.read_text();replacement=START+'\n'+block+'\n'+END
        if START in text:
            assert text.count(START)==text.count(END)==1
            begin=text.index(START);end=text.index(END)+len(END);updated=text[:begin]+replacement+text[end:]
        else:
            # Put core percentages immediately after the title; front page below introduction.
            position=text.index('\n')+1;updated=text[:position]+'\n'+replacement+'\n'+text[position:]
        if updated!=text:
            if args.check:bad.append(path)
            else:target.write_text(updated)
    if bad:raise SystemExit('Completion docs stale: '+', '.join(bad))
    print('Completion ledger and 12 core profiles plus Switch documentation synchronized')
if __name__=='__main__':main()
